// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime, address sender, uint256 initialFunds) public {
        vm.assume(uint160(sender) > 255 && sender != address(this) && sender != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && sender != 0x000000000000000000636F6e736F6c652e6c6f67 && sender != 0x4e59b44847b379578588920cA78FbF26c0B4956C && sender != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);

        vm.assume(blockNum > 0);
        vm.assume(warpTime > 0);
        vm.assume(sender != address(this) && sender != address(c));
        initialFunds = bound(initialFunds, 1, 1000 ether);
        vm.deal(address(c), initialFunds);

        vm.deal(sender, 10 ether);
        vm.warp(warpTime);
        vm.roll(blockNum);

        uint256 balBefore = address(c).balance;

        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "fallback call reverted unexpectedly");

        uint256 balAfter = address(c).balance;

        if (blockNum % 15 == 0) {
            assertEq(balAfter, 0);
        } else {
            assertEq(balAfter, balBefore + 10 ether);
        }
    }
}
